#!/usr/bin/env bash
# The tiers' inputs, the same on every host: apache/parquet-testing at tools/check/corpus.pin, and the fixtures the
# unit tests read from data/, generated by tools/zpq-gen and remade whenever their recipes change. A test that finds
# a fixture missing then fails the tier as a skip, so this step is what makes "missing" impossible, not optional.
set -euo pipefail
cd "$(dirname "$0")/../.."
PY=$(command -v "${PYTHON:-$([ -x .venv/bin/python ] && echo .venv/bin/python || echo python3)}")
[[ $PY == /* ]] || PY=$PWD/$PY  # recipes run from tools/; a venv's python must keep its own path, not its target
pin=$(cat tools/check/corpus.pin)
corpus=data/parquet-testing
mkdir -p data
if [[ ! -e "$corpus/.git" ]]; then
  git clone --quiet --filter=blob:none --no-checkout https://github.com/apache/parquet-testing "$corpus"
fi
if [[ $(git -C "$corpus" rev-parse HEAD 2>/dev/null) != "$pin" ]]; then
  git -C "$corpus" fetch --quiet --depth 1 origin "$pin"
  git -C "$corpus" checkout --quiet --detach "$pin"
fi
[[ $(git -C "$corpus" rev-parse HEAD) == "$pin" ]] || { echo "fixtures: $corpus is not at $pin" >&2; exit 1; }
stamp=$(cat tools/datagen/*.py | sha256sum | cut -c1-16)
for spec in bench:benchmark_100mb.parquet,bench_types.parquet nested:nested_edges.parquet; do
  recipe=${spec%%:*}
  files=${spec#*:}
  fresh=1
  for f in ${files//,/ }; do
    [[ -f data/$f && $(cat "data/.$f.recipe" 2>/dev/null) == "$stamp" ]] || fresh=0
  done
  if [[ $fresh == 0 ]]; then
    (cd tools && "$PY" -m datagen "$recipe" --out ../data >/dev/null)
    for f in ${files//,/ }; do echo "$stamp" > "data/.$f.recipe"; done
  fi
done
echo "fixtures: parquet-testing $pin; $(cd data && ls *.parquet | tr '\n' ' ')"
